  "hardwareTuning": {
    "node": "yeti-cachy",
    "osKernel": "CachyOS Linux \u00b7 CUDA 13.5 \u00b7 NVIDIA Driver 620.73.04",
    "storage": "Dedicated NVMe ext4 model volume + symlinks for PLE streaming and weights",
    "findings": [
      {
        "title": "Alder Lake P-Core vs E-Core Pinning",
        "status": "Verified & Active",
        "detail": "GPU-offloaded LLM profiles pin to P-core logical CPUs `0-11` (`taskset -c 0-11`). Recruiting E-cores `12-15` into Strata's worker pool (`--aux-cpus auto` / `0-15`) regressed decode by -9.8 t/s due to barrier latency. On Inkling 2 Mini, `-t 12` (44.1 t/s) beat physical-only `-t 6` (38.1 t/s). E-cores `12-15` are reserved for non-exclusive co-resident utilities (`embeddinggemma-2`)."
      },
      {
        "title": "DDR5-4800 JEDEC 2DPC Floor (60.0 GB/s)",
        "status": "Confirmed by Microbench",
        "detail": "Live `inxi -m` confirmed 4x16 GiB DDR5 running at 4800 MT/s (2DPC), matching the measured 60.0 GB/s 12-thread CPU read ceiling. Every offloaded MoE miss hits this floor, which is why raising GPU expert cache hit rate (STRATA_HC_Q8=1, --vram-pool, STRATA_ADAPT_FETCH=1) yields outsized decode gains."
      },
      {
        "title": "CPU Governor & Zram Swappiness Hygiene",
        "status": "Active + Monitored",
        "detail": "Benchmarks gate on `cpupower.service` (`performance` governor); `powersave` throttles DDR5 bus switches and collapses decode from 12.2 to 6.5 t/s. Live audit flagged CachyOS default `vm.swappiness=150` paging 6.6 GiB into zram while 37 GiB RAM sat free; tuning `vm.swappiness=10` keeps hot host experts out of zram."
      },
      {
        "title": "NVMe PLE Stream & Page-Cache Isolation",
        "status": "Enforced",
        "detail": "Qwen3.8-Flash-Next's 54.4 GB Q8_0 PLE table stays on NVMe (`--ple-io direct` on Strata, `-ot per_layer_token_embd.weight=CPU` on llama.cpp). Never pass `--ple-io mmap` on Strata or `--mlock` on Qwen3.8: mmapping 30-54 GB of PLE evicts the 39.4 GB expert arena from RAM and triggers heavy SSD refaulting (`0.1756 MB/tok`)."
      }
    ]
  },
